  function apply(){const state={collection,coast,q:$('#search').value,...Object.fromEntries(keys.map(k=>[k,$('#'+k).value])),sort:$('#sort').value};filtered=customMode?myCrate.ids.map(id=>songs.find(s=>s.id===id)).filter(s=>s&&(!state.q||norm([s.title,s.artist,...s.samples.map(x=>x.title+' '+x.artist)].join(' ')).includes(norm(state.q)))):window.CrateFilter(songs,state);if(!started){queue=playableIds(filtered);if(queue.length)loadSong(songs.findIndex(x=>x.id===queue[0]),false)}resultPage=1;expandedCount=50;paintResults();$('#count').textContent=filtered.length+' / '+songs.length+' RECORDS';$('#play-filter').disabled=!playableIds(filtered).length;$('#play-filter').textContent=customMode?'この選曲で連続再生 ▶':'この条件で連続再生 ▶';$('#my-crate-settings').hidden=!customMode;$('#library-tab').setAttribute('aria-pressed',String(!customMode));$('#my-crate-tab').setAttribute('aria-pressed',String(customMode));for(const sel of ['.crate-choices','.crate-current','.advanced-filters','.crate-sort'])$(sel).hidden=customMode;const params=new URLSearchParams();Object.entries(state).forEach(([k,v])=>{if(v&&!(k==='sort'&&v==='year')&&!((k==='collection'||k==='coast')&&v==='all'))params.set(k,v)});history.replaceState(null,'',params.size?'#/?'+params.toString():listBase);$('#hero').hidden=params.size>0||listBase==='#/songs';view.querySelectorAll('[data-crate]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.crate===collection)));view.querySelectorAll('[data-coast]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.coast===coast)));const chosen=scenes.find(x=>x[0]===collection);$('#crate-caption').textContent=chosen[2]+(coast==='all'?'':' · '+coasts.find(x=>x[0]===coast)[1]);$('#clear-browse').disabled=collection==='all'&&coast==='all'&&!state.q&&!keys.some(k=>state[k]);}
  applyListFilters=apply;$('#library-tab').onclick=()=>{customMode=false;apply()};$('#my-crate-tab').onclick=()=>{customMode=true;$('#search').value='';apply()};const saveCrateName=()=>{const ok=myCrate.rename($('#my-crate-name').value);$('#my-crate-name').value=myCrate.name;$('#my-crate-tab').textContent=myCrate.name+' · '+myCrate.ids.length+'曲';savedSelection(ok,'プレイリスト名を保存しました。')};$('#my-crate-name').onchange=saveCrateName;$('#my-crate-save').onclick=saveCrateName;
  $('#view-toggle').onclick=()=>{listMode=listMode==='compact'?'detail':'compact';$('#view-toggle').textContent=listMode==='compact'?'詳しい表示に切り替え':'コンパクト表示に切り替え';$('#view-toggle').setAttribute('aria-pressed',String(listMode==='detail'));paintResults()};view.querySelectorAll('[data-crate]').forEach(b=>b.onclick=()=>{collection=b.dataset.crate;apply()});view.querySelectorAll('[data-coast]').forEach(b=>b.onclick=()=>{coast=b.dataset.coast;apply()});$('#clear-browse').onclick=()=>{collection='all';coast='all';$('#search').value='';keys.forEach(k=>$('#'+k).value='');apply()};$('#search').oninput=apply;[...keys,'sort'].forEach(k=>$('#'+k).onchange=apply);$('#reset').onclick=()=>{collection='all';coast='all';$('#search').value='';keys.forEach(k=>$('#'+k).value='');$('#sort').value='year';apply()};$('#play-filter').onclick=()=>{queue=playableIds(filtered);if(!queue.length){status('再生できる曲がありません。外した曲を戻すか、選曲を追加してください。');return}if(!ready){status('YouTubeの読み込み後にもう一度押してください。');return}started=true;$('#start').hidden=true;const i=songs.findIndex(s=>s.id===queue[0]);if(location.hash==='#/song/'+queue[0])startSong(i);else location.hash='#/song/'+queue[0]};apply();
